import { jev } from "../../core/client.ts";
import { choice } from "../../core/helpers.ts";
import type { ChoiceAnswer } from "../../core/types.ts";

export type Route = "engineering" | "billing" | "product" | "human";
export type Priority = "low" | "normal" | "high";

export type TicketTriage = {
  route: Route;
  priority: Priority;
};

const ROUTES: Record<string, Route> = {
  bug_report: "engineering",
  billing: "billing",
  feature_request: "product",
  other: "human",
};

export async function triageTicket(ticket: string): Promise<TicketTriage> {
  const { answers } = await jev.systemOne({ ticket }, {
    category: choice("What kind of ticket is `ticket`?", {
      bug_report: "Something is broken, crashes, freezes, or behaves wrong",
      billing: "Charges, invoices, refunds, subscriptions",
      feature_request: "Asks for something that does not exist yet",
      other: "None of the above",
    }),
    priority: choice("How urgent is `ticket`?", {
      low: "A suggestion, a cosmetic issue, or a question with no deadline",
      normal: "A real problem, but the author can keep working",
      high: "The author is blocked, losing money or customers, or very angry",
    }),
  });

  const category = answers.category as ChoiceAnswer;
  const priority = answers.priority as ChoiceAnswer;
  return { route: ROUTES[category.choice], priority: priority.choice as Priority };
}

import { jev } from "../../core/client.ts";
import { choice } from "../../core/helpers.ts";
import type { ChoiceAnswer } from "../../core/types.ts";

export type Seniority = "junior" | "mid" | "senior";
export type Match = "different_field" | "partial" | "strong";

export type ResumeVerdict = {
  proceed: boolean;
  seniority: Seniority;
  match: Match;
};

export async function screenResume(resume: string, jobDescription: string): Promise<ResumeVerdict> {
  const { answers } = await jev.systemOne({ resume, job_description: jobDescription }, {
    seniority: choice("How senior is the candidate in `resume`?", {
      junior: "Guided work, internships, limited ownership",
      mid: "Owns features end to end",
      senior: "Owns systems, sets direction, mentors others",
    }),
    match: choice("How well does `resume` match `job_description`?", {
      different_field: "Experience is in another discipline entirely",
      partial: "Some of the requirements are met",
      strong: "The requirements are met with directly relevant experience",
    }),
  });

  const seniority = (answers.seniority as ChoiceAnswer).choice as Seniority;
  const match = (answers.match as ChoiceAnswer).choice as Match;
  return { proceed: seniority === "senior" && match === "strong", seniority, match };
}

import { jev } from "../../core/client.ts";
import { choice } from "../../core/helpers.ts";
import type { ChoiceAnswer } from "../../core/types.ts";

export type Intent = "sponsorship" | "support" | "partnership" | "other";
export type ProductCategory = "dev_tool" | "course" | "unrelated";

export type SponsorQualification = {
  autoReply: boolean;
  intent: Intent;
  category: ProductCategory;
};

export async function qualifySponsorForm(form: {
  name: string;
  description: string;
  opportunity: string;
}): Promise<SponsorQualification> {
  const { answers } = await jev.systemOne(form, {
    intent: choice("What does the sender of `description` want?", {
      sponsorship: "To pay for placement in the site or newsletter",
      support: "Help with an account, a login, or something broken",
      partnership: "A collaboration, cross-promotion, or content swap with no payment mentioned",
      other: "None of the above",
    }),
    category: choice("What kind of product is described by `name` and `description`?", {
      dev_tool: "Developer tools, hosting, APIs, SaaS for developers",
      course: "Courses, books, or training",
      unrelated: "Anything not aimed at developers",
    }),
  });

  const intent = (answers.intent as ChoiceAnswer).choice as Intent;
  const category = (answers.category as ChoiceAnswer).choice as ProductCategory;
  return { autoReply: intent === "sponsorship" && category === "dev_tool", intent, category };
}
